package io.github.ningpp.compat;

/**
 * Replacement for System.Buffers.BuffersExtensions (generated by CSharpToJava converter).
 *
 * <p>The .NET CopyTo/ToArray overloads cover the WHOLE sequence, not just its first
 * segment, so every method here iterates all segments. Multi-segment sequences really
 * occur end to end: once ReadOnlySequence.slice preserves segments, a generated
 * Utf8JsonReader value token that spans buffers has HasValueSequence == true and flows
 * through {@code BuffersExtensions.toByteArray(getValueSequence())} in every Get* method.
 */
public final class BuffersExtensions {
    private BuffersExtensions() {
    }

    /** Mirrors BuffersExtensions.CopyTo(ReadOnlySequence&lt;T&gt;, Span&lt;T&gt;) — copies the sequence into the span. */
    public static <T> void copyTo(ReadOnlySequence<T> sequence, Span<T> destination) {
        int written = 0;
        for (ReadOnlyMemory<T> memory : sequence) {
            ReadOnlySpan<T> span = memory.getSpan();
            for (int i = 0; i < span.length(); i++) {
                if (written >= destination.length()) {
                    return;
                }
                destination.set(written++, span.get(i));
            }
        }
    }

    /** Mirrors BuffersExtensions.CopyTo(ReadOnlySequence&lt;T&gt;, ReadOnlySpan&lt;T&gt;) — read-only destination variant. */
    public static <T> void copyTo(ReadOnlySequence<T> sequence, ReadOnlySpan<T> destination) {
        int written = 0;
        for (ReadOnlyMemory<T> memory : sequence) {
            ReadOnlySpan<T> span = memory.getSpan();
            for (int i = 0; i < span.length(); i++) {
                if (written >= destination.length()) {
                    return;
                }
                destination.set(written++, span.get(i));
            }
        }
    }

    /** Mirrors BuffersExtensions.ToArray(ReadOnlySequence&lt;T&gt;) — result is a genuinely typed T[]. */
    public static <T> T[] toArray(ReadOnlySequence<T> sequence) {
        java.util.List<T[]> materialized = new java.util.ArrayList<>();
        int total = 0;
        Class<?> componentType = null;
        for (ReadOnlyMemory<T> memory : sequence) {
            T[] part = memory.toArray(); // per-segment typing, like ReadOnlyMemory.toArray
            materialized.add(part);
            total += part.length;
            if (componentType == null && part.length > 0) {
                componentType = part.getClass().getComponentType();
            }
        }
        if (componentType == null) {
            componentType = Object.class;
        }
        @SuppressWarnings("unchecked")
        T[] result = (T[]) java.lang.reflect.Array.newInstance(componentType, total);
        int written = 0;
        for (T[] part : materialized) {
            System.arraycopy(part, 0, result, written, part.length);
            written += part.length;
        }
        return result;
    }

    /** Mirrors BuffersExtensions.ToArray(ReadOnlySequence&lt;byte&gt;) — byte[] per the C# contract. */
    public static byte[] toByteArray(ReadOnlySequence<Integer> sequence) {
        byte[] result = new byte[(int) sequence.getLength()];
        int written = 0;
        for (ReadOnlyMemory<Integer> memory : sequence) {
            ReadOnlySpan<Integer> span = memory.getSpan();
            for (int i = 0; i < span.length(); i++) {
                result[written++] = (byte) (span.get(i) & 0xFF);
            }
        }
        return result;
    }
}
